function renderLegend(container, names, onToggle) {
  container.innerHTML = "";
  const crumbs = new Map(); // build separate to handle isolation state
  const state = names.map(() => {"on":true});
  container.innerHTML = "";
  names.forEach((n, i) => {
    const item = document.createElement("div");
    item.className = "item";
    item.innerHTML = `<span class="sw" style="--sc:${css(SRC.series[i])}"></span><span>${esc(n)}</span>`;
    item.addEventListener("click", () => {
      const allOn = [...container.children].every(el => !el.classList.contains("dim"));
      container.querySelectorAll(".item").forEach(el =>
        el.classList.toggle("dim", allOn ? el !== item : false));
      onToggle();
    });
    container.appendChild(item);
  });
}

