function slice() {
  const [a, b] = RANGES[range];
  const rev  = DATA.rev_total.slice(a, b);
  const ses  = DATA.ses_total.slice(a, b);
  const cvr  = DATA.conv_rate;              // [channel][month] (percent)
  const cvrByMonth = MONTHS.map((_, m) =>
    cvr.reduce((s, ch) => s + ch[m] * (DATA.monthly_sessions.reduce((t,c)=>t+c[m],0)>0 ?
      DATA.monthly_sessions.reduce((t,c)=>t+c[m],0) : 1), 0) /
    DATA.monthly_sessions.reduce((t,c)=>t+c[m],0));
  // weighted mean conversion % by month
  for (let m = 0; m < MONTHS.length; m++) {
    const totS = DATA.monthly_sessions.reduce((t, c) => t + c[m], 0);
    let w = 0; for (let c = 0; c < CHANNELS.length; c++)
      w += cvr[c][m] * DATA.monthly_sessions[c][m];
    cvrByMonth[m] = totS ? w / totS : 0;
  }
  const prev = RANGES[range][0];
  const prevRev = DATA.rev_total.slice(Math.max(0, a - (b - a)), a);
  return {
    months: MONTHS.slice(a, b),
    rev, ses,
    cvr: cvrByMonth.slice(a, b),
    arps: rev.map((r, i) => r * 1000 / (ses[i] || 1)),
    prevRev: prevRev.length ? prevRev.reduce((x, y) => x + y, 0) : 0,
  };
}

