function renderKPIs() {
  const s = slice();
  const curRev = s.rev.reduce((x, y) => x + y, 0);
  const curSes = s.ses.reduce((x, y) => x + y, 0);
  const curCvr = s.cvr.length ? s.cvr.reduce((x, y) => x + y, 0) / s.cvr.length : 0;
  const curArps = curSes ? (curRev * 1000) / curSes : 0;

  const prevArps = s.prevSes ? (s.prevRev * 1000) / s.prevSes : 0;
  $("#heroVal").innerHTML = "$" + fmt(curRev) + "<small>k</small>";
  $("#heroDelta").textContent = pct(curRev, s.prevRev);
  $("#kpiSes").textContent = fmtK(curSes);
  $("#kpiSesD").textContent = pct(curSes, s.prevSes);
  $("#kpiConv").textContent = curCvr.toFixed(1) + "%";
  const convSpan = s.cvr[s.cvr.length - 1] - s.cvr[0];
  $("#kpiConvD").textContent = (convSpan >= 0 ? "+" : "") + convSpan.toFixed(1) + " pp";
  $("#kpiArps").textContent = "$" + curArps.toFixed(2);
  const arpsD = (curArps - prevArps) * 100 / (prevArps || 1);
  $("#kpiArpsD").textContent = (arpsD >= 0 ? "+" : "") + arpsD.toFixed(1) + "%";
  // sparklines
  spark($("#sparkSes"), s.ses, "var(--ink-3)");
  spark($("#sparkConv"), s.cvr, "var(--ink-3)");
  spark($("#sparkArps"), s.arps, "var(--ink-3)");
}
function spark(svg, vals, color) {
  const W = 140, H = 34, P = 2;
  if (!vals.length) return;
  const min = Math.min(...vals), max = Math.max(...vals);
  const rng = (max - min) || 1;
  const pts = vals.map((v, i) => {
    const x = P + (i / (vals.length - 1)) * (W - 2 * P);
    const y = H - P - ((v - min) / rng) * (H - 2 * P);
    return [x, y];
  });
  const d = pts.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ");
  svg.innerHTML = `<path d="${d}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"></path>`;
}

/* ===================================================================
   Legend: toggle-to-isolate; color follows the entity, never rank.
   =================================================================== */
function renderLegend(container, names, onToggle) {
  container.innerHTML = "";
  names.forEach((n, i) => {
    const item = document.createElement("div");
    item.className = "item";
    item.innerHTML = `<span class="sw" style="--sc:${css(SRC.series[i])}"></span><span>${esc(n)}</span>`;
    item.addEventListener("click", () => {
      const allOn = [...container.children].every(el => !el.classList.contains("dim"));
      container.querySelectorAll(".item").forEach(el =>
        el.classList.toggle("dim", allOn ? el !== item : false));
      onToggle();
    });
    container.appendChild(item);

