function renderChart2() {
  const s = slice();
  const svg = $("#chart2");
  const W = 880, H = 300, mL = 200, mR = 20, mT = 10, mB = 26;
  const iw = W - mL - mR;

  // compute shares over the current slice
  const [a, b] = RANGES[range];
  const per = DATA.monthly_sessions.map(ch => ch.slice(a, b).reduce((x, y) => x + y, 0));
  const tot = per.reduce((x, y) => x + y, 0) || 1;
  const share = per.map(v => (v / tot) * 100);

  const barH = 44, y0 = mT;
  const dimmed = legendDimmed($("#legend2"));
  let body = "";
  const colR = iw - 120;
  let acc = 0;
  const segs = CHANNELS.map((ch, c) => {
    const w = (share[c] / 100) * colR;
    const x0 = mL + acc;
    const x1 = x0 + w;
    body += `<rect x="${x0}" y="${y0}" width="${Math.max(w, 0)}" height="${barH}" rx="6"
             fill="${css(SRC.series[c])}" data-c="${c}"></rect>`;
    acc += w;
    return { c, x0, x1, p: share[c], w };
  });
  const last = segs[segs.length - 1];
  // total label at the tip
  body += `<text class="endlabel" x="${mL + colR + 10}" y="${y0 + barH / 2 + 3.5}">${fmt(tot)}</text>`;

  svg.innerHTML = body +
    `<g class="legend-labels"></g><g class="hover"></g><g class="axis"></g>`;

  // segment data labels — only when the label fits (≥4% share)
  segs.forEach((seg) => {
    if (seg.p < 4) return; // label won't fit — tooltip/table carry it
    const cx = (seg.x0 + seg.x1) / 2;
    svg.querySelector(".legend-labels").insertAdjacentHTML("beforeend",
