   Chart 3 — Sessions heatmap (sequential blue ramp, weekday x month)
   =================================================================== */
const HEAT_STEPS = ["#cde2fb","#9ec5f4","#6da7ec","#3987e5","#256abf","#1c5cab","#104281"];
function renderChart3() {
  const svg = $("#chart3");
  const W = 880, H = 360, mL = 48, mR = 12, mT = 12, mB = 30;
  const iw = W - mL - mR, ih = H - mT - mB;
  const [a, b] = RANGES[range];
  const cols = b - a;
  const cw = iw / cols, ch = ih / 7;
  const heat = DATA.heatmap;
  const maxHeat = Math.max(...heat.map(r => Math.max(...r.slice(a, b))));
  const minHeat = Math.min(...heat.map(r => Math.min(...r.slice(a, b))));

  let body = "";
  heat.forEach((row, w) => {
    row.slice(a, b).forEach((v, mi) => {
      const m0 = a + mi;
      const t = (v - minHeat) / (maxHeat - minHeat || 1);
      const col = HEAT_STEPS[Math.min(HEAT_STEPS.length - 1, Math.max(0, Math.round(t * (HEAT_STEPS.length - 1))))];
      const x0 = mL + mi * cw, y0 = mT + w * ch;
      body += `<rect x="${x0}" y="${y0}" width="${cw}" height="${ch}" rx="3"
               fill="${col}" data-w="${w}" data-m="${m0}"></rect>`;
    });
  });

  // month labels (top) + weekday labels (left)
  MONTHS.slice(a, b).forEach((mm, mi) => {
    body += `<text x="${mL + mi * cw + cw / 2}" y="${mT - 6}" text-anchor="middle">${mm}</text>`;
  });
  WEEKDAYS.forEach((wd, w) => {
    body += `<text x="${mL - 8}" y="${mT + w * ch + ch / 2 + 4}" text-anchor="end">${wd}</text>`;
  });

  svg.innerHTML = body + `<g class="hover"></g>`;
  // scale legend (blue ramp) in the top-right
  svg.insertAdjacentHTML("beforeend", scaleLegend(maxHeat, minHeat));

  // hover: mark is the hit target
  svg.querySelectorAll("rect[data-w]").forEach(r => {
    const w = +r.dataset.w, m = +r.dataset.m;
    const bind = ev => {
      const rr = svg.getBoundingClientRect();
      const cx = rr.left + (+r.getAttribute("x")) + cw / 2;
      const cy = rr.top + (+r.getAttribute("y")) + ch / 2;

