function analyze(id, vbw, vbh) {
  const svg = window.document.getElementById(id);
  const texts = [...svg.querySelectorAll('text')].map(t=>({
    x:+t.getAttribute('x'), y:+t.getAttribute('y'),
    anchor:t.getAttribute('text-anchor')||'start',
    cls:t.getAttribute('class')||'',
    txt:t.textContent,
  }));
  const W=vbw, H=vbh;
  console.log(`\n=== ${id} (${W}x${H}) ===`);
  const approx=(txt,n)=>{const w=n*txt.length;
    // glyph ~ 11px for 11.5/12px font; estimate width per char ~0.55*fontsize
    return 0.6*(txt.match(/[^0-9.,$%k ]/g)?txt.length:txt.length)*11 * (txt.length?1:0);
  };
  let issues=[];
  for(const t of texts){
    const estW=6.5*t.txt.length;
    let x0,x1;
    if(t.anchor==='middle'){ x0=t.x-estW/2; x1=t.x+estW/2; }
    else if(t.anchor==='end'){ x0=t.x-estW; x1=t.x; }
    else { x0=t.x; x1=t.x+estW; }
    if(x0< -2 || x1> W+2) issues.push(`OVERFLOW-X: "${t.txt}" anchor=${t.anchor} x=${t.x} est[${x0.toFixed(0)},${x1.toFixed(0)}]`);
    if(t.y<0 || t.y>H+2) issues.push(`OVERFLOW-Y: "${t.txt}" y=${t.y}`);
  }
  console.log('text elements:', texts.length);
  if(issues.length){ issues.forEach(i=>console.log('  !!',i)); } else console.log('  no x/y overflow detected');
  return texts;
}

