const svg = $("#chart1");
const W = 880, H = 380, mL = 62, mR = 92, mT = 16, mB = 34;
const iw = W - mL - mR, ih = H - mT - mB;
const n = s.months.length;
const maxAll = Math.max(...CHANNELS.map((_, c) =>
  Math.max(...sliceRange(c).map(x => x))));
function sliceRange(c) {
  const [a, b] = RANGES[range];
  return DATA.monthly_revenue[c].slice(a, b);
}
const x = i => mL + (n === 1 ? iw / 2 : (i / (n - 1)) * iw);
const y = v => mT + ih - (v / maxAll) * ih;
const dimmed = legendDimmed($("#legend1"));

// gridlines + axis
let g = "";
const ticks = 4;
for (let t = 0; t <= ticks; t++) {
  const v = (maxAll * t) / ticks;
  const yy = y(v);
  g += `<line x1="${mL}" y1="${yy}" x2="${W - mR}" y2="${yy}"></line>` +
       `<text x="${mL - 8}" y="${yy + 3.5}" text-anchor="end">${numFmt(v)}</text>`;
}
g += `<line x1="${mL}" y1="${mT + ih}" x2="${W - mR}" y2="${mT + ih}" class="zero"></line>`;
s.months.forEach((m, i) => {
  g += `<text x="${x(i)}" y="${H - 8}" text-anchor="middle">${m}</text>`;
});

// series lines
let body = "";
const paths = [];
CHANNELS.forEach((ch, c) => {
  if (dimmed.includes(c)) return;
  const vals = sliceRange(c);
  const col = css(SRC.series[c]);
  const d = vals.map((v, i) => (i ? "L" : "M") + x(i).toFixed(1) + " " + y(v).toFixed(1)).join(" ");
  paths[c] = d;
  body += `<path d="${d}" fill="none" stroke="${col}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"></path>`;
  // end marker (direct label: the endpoint)
  const lx = x(n - 1), ly = y(vals[n - 1]);

