input.new_string:
// series lines (color follows the entity — survivors keep their hue)
let body = "";
const ends = [];   // {c, y, v} endpoints for leader-line placement
CHANNELS.forEach((ch, c) => {
  if (dimmed.includes(c)) return;
  const vals = sliceRange(c);
  const col = css(SRC.series[c]);
  const d = vals.map((v, i) => (i ? "L" : "M") + x(i).toFixed(1) + " " + y(v).toFixed(1)).join(" ");
  body += `<path d="${d}" fill="none" stroke="${col}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"></path>`;
  // end marker dot (2px surface ring keeps it legible over the line)
  const lx = x(n - 1), ly = y(vals[n - 1]);
  body += `<circle cx="${lx}" cy="${ly}" r="4" fill="${col}" stroke="var(--surface-1)" stroke-width="2"></circle>`;
  ends.push({ c, x: lx, y: ly, v: vals[n - 1], ch });
});

// direct end-labels with leader lines. Ends sit at the same x as the lines
// converge at the right edge, so stack labels vertically with a 14px line pitch
// and connect each label to its line-end with a thin leader.
const labelX = x(n - 1) + 14 + 70;   // right margin holds the label column
const sorted = [...ends].sort((a, b) => a.y - b.y);
let labelY0 = sorted[0] ? Math.max(mT + 8, sorted[0].y - 8) : mT + 8;
sorted.forEach((e, idx) => {
  const rowY = labelY0 + idx * 16;   // 16px pitch prevents vertical collision
  const col = css(SRC.series[e.c]);
  // leader: from the line-end dot to the label column
  body += `<line x1="${e.x + 5}" y1="${e.y}" x2="${labelX - 6}" y2="${rowY}"
                  stroke="${col}" stroke-width="1" opacity="0.5"></line>` +
          `<text class="endlabel" x="${labelX}" y="${rowY + 3.5}">${esc(e.ch)} $${numFmt(e.v)}k</text>`;
});

