cd /tmp/pptr
cat > /tmp/fullcheck.js <<'JS'
const { JSDOM } = require('/tmp/pptr/node_modules/jsdom');
const fs = require('fs');
const html = fs.readFileSync('/workspace/index.html','utf8');
const data = JSON.stringify(require('/tmp/dash_data.js'));
const hw = html.replace('/*__DATA_JSON__*/', 'const DATA = '+data+';');
const VARS = {"--series-1":"#2a78d6","--series-2":"#eb6834","--series-3":"#1baf7a","--series-4":"#eda100","--ink-1":"#0b0b0b","--ink-2":"#52514e","--ink-3":"#898781","--grid":"#e1e0d9","--axis":"#c3c2b7","--border":"rgba(11,11,11,.1)","--surface-1":"#fcfcfb","--delta-up":"#006300"};

const RANGES = { ytd:[0,8], "6m":[6,12], q4:[9,12], all:[0,12] };
let failures = 0;

for (const [rng,[a,b]] of Object.entries(RANGES)) {
  const dom = new JSDOM(hw, { runScripts:'outside-only', pretendToBeVisual:true });
  const { window } = dom;
  Object.defineProperty(window,'getComputedStyle',{value:()=>({getPropertyValue:n=>VARS[n]||''})});
  Object.defineProperty(window,'matchMedia',{value:()=>({matches:false,addEventListener(){}})});
  window.innerWidth=1160;
  try {
    window.eval(window.document.querySelector('script').textContent.replace('/*__DATA_JSON__*/','const DATA = '+data+';'));
    // simulate selecting the range
    window.range = rng;
    window.renderAll();
  } catch(e){ failures++; console.log(`[${rng}] RENDER ERROR:`, e.message); continue; }

  const d = window.document;
  const nMonths = b-a;
  // chart1 x-labels should equal nMonths
  const xlabels = [...d.getElementById('chart1').querySelectorAll('.grid-h text')]
    .filter(t=>t.getAttribute('text-anchor')==='middle').length;
  if (xlabels !== nMonths) { failures++; console.log(`[${rng}] chart1 month labels ${xlabels} != ${nMonths}`); }
  // chart1 end labels count == channels (unless dimmed none)
  const ends = d.getElementById('chart1').querySelectorAll('.endlabel').length;
  if (ends !== 4) { failures++; console.log(`[${rng}] chart1 end labels ${ends} != 4`); }
  // chart2: 4 bar rects + total label
  const bars = d.getElementById('chart2').querySelectorAll('rect[data-c]').length;
  if (bars !== 4) { failures++; console.log(`[${rng}] chart2 bars ${bars}`); }
  // chart2 segments should sum to ~100%
  const segs=[...d.getElementById('chart2').querySelectorAll('rect[data-c]')]
    .map(r=>+r.getAttribute('width'));
  const cw = [...d.getElementById('chart3').querySelectorAll('rect[data-w]')].length;
  const expCells = 7 * nMonths;
  if (cw !== expCells) { failures++; console.log(`[${rng}] heat cells ${cw} != ${expCells}`); }
  // check a bar width isn't NaN
  if (segs.some(isNaN)) { failures++; console.log(`[${rng}] NaN bar width in chart2`); }

  // KPI values present
  const hero = d.getElementById('heroVal').textContent;
  if (!hero || hero==='$0k') { failures++; console.log(`[${rng}] hero looks off: "${hero}"`); }
  console.log(`[${rng}] months=${nMonths} chart1labels=${xlabels} ends=${ends} bars=${bars} heatcells=${cw} hero="${hero}" OK`);
  dom.window.close();
}
console.log(failures===0 ? '\nALL RANGES PASS' : `\n${failures} FAILURES`);
